export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = [];

  const pendingById = new Map();
  const listeners = [];

  function notify() {
    const snapshot = listeners.slice();

    for (const subscription of snapshot) {
      const listener = subscription.listener;

      try {
        listener();
      } catch {
        // Listener errors do not interrupt notification.
      }
    }
  }

  function getState() {
    return visible;
  }

  function apply(id, update) {
    if (pendingById.has(id)) {
      throw new Error("A pending change with this id already exists");
    }

    const nextVisible = update(visible);
    const change = { id, update };

    pending.push(change);
    pendingById.set(id, change);
    visible = nextVisible;

    notify();
  }

  function confirm(id) {
    const change = pendingById.get(id);

    if (!change) {
      return false;
    }

    const confirmedUpdate = change.update;
    const nextBase = confirmedUpdate(base);
    const nextPending = [];
    let nextVisible = nextBase;

    for (const current of pending) {
      if (current === change) {
        continue;
      }

      nextPending.push(current);
      const pendingUpdate = current.update;
      nextVisible = pendingUpdate(nextVisible);
    }

    base = nextBase;
    pending = nextPending;
    pendingById.delete(id);
    visible = nextVisible;

    notify();
    return true;
  }

  function rollback(id) {
    const change = pendingById.get(id);

    if (!change) {
      return false;
    }

    const nextPending = [];
    let nextVisible = base;

    for (const current of pending) {
      if (current === change) {
        continue;
      }

      nextPending.push(current);
      const pendingUpdate = current.update;
      nextVisible = pendingUpdate(nextVisible);
    }

    pending = nextPending;
    pendingById.delete(id);
    visible = nextVisible;

    notify();
    return true;
  }

  function subscribe(listener) {
    const subscription = { listener };
    let subscribed = true;

    listeners.push(subscription);

    return function unsubscribe() {
      if (!subscribed) {
        return;
      }

      subscribed = false;
      const index = listeners.indexOf(subscription);

      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  return {
    getState,
    apply,
    confirm,
    rollback,
    subscribe,
  };
}
